args.sparql:
SELECT ?r ?g ?b WHERE {
  :Ruby x3do:diffuseColor ?c .
  ?c rdf:first ?r ; rdf:rest/rdf:first ?g ; rdf:rest/rdf:rest/rdf:first ?b
}

SELECT ?material ?Y WHERE {
  ?material a x3do:Material ; x3do:diffuseColor ?c .
  ?c rdf:first ?r ; rdf:rest/rdf:first ?g ; rdf:rest/rdf:rest/rdf:first ?b .
  BIND(0.2126 * ?r + 0.7152 * ?g + 0.0722 * ?b AS ?Y)
  FILTER(?Y > 0.2)
} ORDER BY DESC(?Y)

SELECT ?shape WHERE {
  ?shape a x3do:Shape .
  OPTIONAL { ?shape x3do:hasAppearance ?appearance }
  FILTER(!BOUND(?appearance))
}

SELECT ?from ?via ?to ?toField WHERE {
  ?r1 a x3do:ROUTE ; x3do:fromNode ?from ; x3do:toNode ?via .
  ?r2 a x3do:ROUTE ; x3do:fromNode ?via ; x3do:toNode ?to ; x3do:toField ?toField .
}

SELECT ?type (COUNT(?node) AS ?count) WHERE {
  ?node a ?type .
  FILTER(STRSTARTS(STR(?type), STR(x3do:)))
} GROUP BY ?type ORDER BY DESC(?count) ?type

SELECT ?route ?end ?name WHERE {
  ?route a x3do:ROUTE .
  { ?route x3do:fromNode ?name BIND("fromNode" AS ?end) } UNION { ?route x3do:toNode ?name BIND("toNode" AS ?end) }
  FILTER NOT EXISTS { ?node x3do:DEF ?name }
}

